PNE_st.name='PNE'; 
PNE_st.lat=18.52;
PNE_st.lon=73.86;
PNE_st.alt=0000;
PNE_st.env='Con';
PNE_st.footp='U';
%%
% data imported via the import tool from matlab
 PNE_rd_h = importfile_AE_India("C:\github_trend\raw_data\Aethalometer_India\Aethalometer\PNE_2016-2026_Hour.csv", [2, Inf]);
PNE_rd_h.Properties.DimensionNames{1}='Time';
PNE_rd_h.Properties.VariableNames{2}='Ba1_A';
PNE_rd_h.Properties.VariableNames{3}='Ba2_A';
PNE_rd_h.Properties.VariableNames{4}='Ba3_A';
PNE_rd_h.Properties.VariableNames{5}='Ba4_A';
PNE_rd_h.Properties.VariableNames{6}='Ba5_A';
PNE_rd_h.Properties.VariableNames{7}='Ba6_A';
PNE_rd_h.Properties.VariableNames{8}='Ba7_A';
names_rd=fieldnames(PNE_rd_h);
%%
PNE_rd=retime(PNE_rd_h,'daily',@nanmedian);
%%
datevec(PNE_rd.Time(1)) % begin in 2016,  %[output:7a3f5d0a]
datevec(PNE_rd.Time(end)) % end in 2021 February too short %[output:0c280ed0]
plotFigControl(PNE_rd,PNE_st.name);  %[output:7030742d] %[output:92f916c9] %[output:8a3db4cb] %[output:0941217c] %[output:81f161b9] %[output:7911ff20] %[output:977cd030] %[output:04cba172]
%%
lambdaAE7=[370 470 520 590 660 880 950];
%compute abs exp
Ca3=startsWith(names_rd,{'Ba'}) & contains(names_rd,{'_A'});
names_abs=names_rd(Ca3);
PNE_cal=compute_exp_D(PNE_rd,names_abs,lambdaAE7); %[output:7c63b252] %[output:600ff552]
plotFigControl_cal(PNE_cal,PNE_st.name); %[output:55008897] %[output:8ab30996] %[output:6393573f]
%%
%HOMOGENEITY

break_PNE_abs_BP=change_point_analysis_Def(PNE_rd,names_abs,0.05,'PNE','Absorption'); %[output:6b7ee9f8] %[output:5a393386] %[output:85ed12d1] %[output:4eb1a59d] %[output:9f80f676] %[output:2e5e35fe]
T_PNE_abs_BP=make_table_breakpoints_def(break_PNE_abs_BP);

names_expA={'expA_bgAE','expA_brAE','expA_grAE','expA_fit'} %[output:82c891ea]
break_PNE_expA_BP=change_point_analysis_Def(PNE_cal,names_expA,0.05,'PNE','Absorption exponent'); %[output:5c5b8d3a] %[output:0d281667] %[output:772a8668] %[output:31d5bcfa]
T_PNE_expA_BP=make_table_breakpoints_def(break_PNE_expA_BP);




